class CatalogCache:
    def __init__(self, catalog):
        self.catalog = catalog
        self.entries = {}  # id -> (version, value)

    def get(self, id):
        version = self.catalog.versions.get(id, 0)
        cached = self.entries.get(id)
        if cached is None or cached[0] != version:
            cached = (version, self.catalog.read(id))
            self.entries[id] = cached
        return None if cached[1] is None else dict(cached[1])

